  if(lock)proposal=await call(i,'GET','/ai/actions/'+i.id);
  const raw=(await pool.query('SELECT updated_at,payload,action_type,expires_at FROM finance_ai_action_proposals WHERE id=$1 AND company_id=$2 AND owner_user_id=$3 AND finance_space_id=$4',[i.id,actor.companyId,actor.userId,i.finance_space_id])).rows[0];
  if(!raw)throw fault(404,'finance_ai_action_not_found');
